; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_div @data
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_rampt @data
ntc_rampt:		dw #7FC0		; the gate array's RAM setting now (B = port, C = value): the
								; Memory class keeps it, Graphics puts it back after drawing

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
	IF NTC_INTS					; (;@ints 0: a platform that never lets interrupts in - the Next's dot commands)
			ei
			nop					; an interrupt can be taken here
			di
	ENDIF
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_modvl kw_divvl
;kw_modvl, <var>, <literal>, <destvar>
kw_modvl:
			ld a, 1
			ld (ntc_mode), a
			jp ntc_divvl

;## kw_andvl
;kw_andvl, <var>, <literal>, <destvar>
kw_andvl:
			pop hl
			pop de
			ld a, (hl)
			and e
			ld e, a
			inc hl
			ld a, (hl)
			and d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## ntc_lcmp ntc_ldata
; DE = a, HL = b: work out a - b. ntc_lsgn = #80 if a < b (signed),
; ntc_lcnt = 0 if a = b. jp (ix) back.
ntc_lcmp:
			ld a, (de)
			sub (hl)
			ld (ntc_lr), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+3), a
			ld b, 0
			jp po, ntc_lcm_nov
			ld b, #80
ntc_lcm_nov:
			xor b
			and #80
			ld (ntc_lsgn), a
			ld hl, ntc_lr
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld (ntc_lcnt), a
			jp (ix)

;## kw_l_cpeq ntc_lcmp
;kw_l_cpeq, <a>, <b>  - Z if a = b
kw_l_cpeq:
			pop de
			pop hl
			ld ix, ntc_lceq
			jp ntc_lcmp
ntc_lceq:
			ld a, (ntc_lcnt)
			or a
			ret

;## kw_l_cpne ntc_lcmp
;kw_l_cpne, <a>, <b>  - Z if a <> b
kw_l_cpne:
			pop de
			pop hl
			ld ix, ntc_lcne
			jp ntc_lcmp
ntc_lcne:
			ld a, (ntc_lcnt)
			or a
			jr z, ntc_lcne_f
			xor a
			ret
ntc_lcne_f:
			or 1
			ret

;## ntc_buf2k
; ntc_buf - a buffer shared by the classes that need one: FileSystem's
; CAS IN / OUT OPEN buffer (CPC firmware: 2K) and Memory.Copy's page to page
; copy (that much at a time). NTC_BUFSIZE (Option Buffer): 2048 unless set
ntc_buf:		ds NTC_BUFSIZE

;## ntc_memcore ntc_data ntc_mem ntc_memcore2 ntc_plat_memtop @shared
; ------------------------------------------------------------
; ntc_memcore - the Memory class, the part every scheme shares. The scheme
; (Option Memory, else the platform's default) is the section ntc_mem -
; only the one chosen is in the library (@if:): CPCExpansion (16K pages
; through the #4000 window, up to 4MB) or Small (main RAM only, no paging).
; Each class method jumps to mem_go with HL = the routine: mem_go runs it
; on the real stack (call / push are fine there), interrupts on in normal
; mode (off in turbo), and stores its HL result at mem_res (mem_go4: a Long, high
; word in mem_hi; mem_go0: no store - the routine writes the result
; itself, or there is none). A routine that fails jumps to mem_err with
; HL = the status; mem_err puts back the page that was in the window
; and unwinds to mem_go.
; Far pointer = a Long: address, page (page 0 = plain memory).
; Heap: blocks from mem_hlo to mem_hhi (a D page, or Small's main RAM),
; each with a 2 byte header: length including the header (always even: any
; size up to the region's), bit 0 = in use. Free neighbours are joined.
; The scheme supplies: mem_start (the first call), mem_sel (HL = page
; into the window), mem_chk (HL = a page number, else BadPage).
; ------------------------------------------------------------
MEM_WIN		equ #4000
MEM_BADPAGE	equ -2

mem_a1:			dw 0
mem_a2:			dw 0
mem_a3:			dw 0
mem_res:		dw 0
mem_hi:			dw 0
mem_sp:			dw 0
mem_esp:		dw 0
mem_six:		dw 0
mem_siy:		dw 0
mem_need:		dw 0
mem_max:		dw 0
mem_srca:		dw 0
mem_dsta:		dw 0
mem_srcp:		dw 0
mem_dstp:		dw 0
mem_left:		dw 0
mem_chunk:		dw 0
mem_cur:		dw 1			; the page in the window
mem_keep:		dw 1			; the page to put back
mem_hlo:		dw MEM_WIN		; the heap region mem_fit / mem_big work in
mem_hhi:		dw #8000
mem_store:		db 0
mem_init:		db 0			; 1 = the first call has been

; mem_go / mem_go4 / mem_go0 - HL = the routine (see above)
mem_go0:
			xor a
			jr mem_gostart
mem_go4:
			ld a, 4
			jr mem_gostart
mem_go:
			ld a, 2
mem_gostart:
			ld (mem_store), a
			ld (mem_sp), sp
			ld sp, (ntc_csp)
			ld (mem_six), ix
			ld (mem_siy), iy
			ld de, 0
			ld (mem_hi), de
			push hl
			call mem_start
			pop hl
			ld de, (mem_cur)
			ld (mem_keep), de
			ld a, (ntc_nmode)		; normal mode: interrupts in during the call (Ticks keep
			or a					; counting through a long Sort or Copy); turbo: off
			jr z, mem_gocall
			ei
mem_gocall:
			ld (mem_esp), sp
			call mem_jphl
mem_back:
			di
			ld ix, (mem_six)
			ld iy, (mem_siy)
			ld a, (mem_store)
			or a
			jr z, mem_gone
			ex de, hl
			ld hl, (mem_res)
			ld (hl), e
			inc hl
			ld (hl), d
			cp 4
			jr nz, mem_gone
			ld de, (mem_hi)
			inc hl
			ld (hl), e
			inc hl
			ld (hl), d
mem_gone:
			ld sp, (mem_sp)
			ret
mem_jphl:
			jp (hl)
mem_err:
			ld sp, (mem_esp)
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ld de, 0
			ld (mem_hi), de
			jr mem_back

mem_chk_bad:
			ld hl, MEM_BADPAGE
			jp mem_err

;## ntc_memcore2 ntc_memcore @shared @far
; ntc_memcore2 - the rest of the shared part: far pointers, the heap, bytes
; and words. Runs on the real stack (through mem_go), so a keyword ROM set
; can place it in another ROM of the set (@far).

; mem_far - HL = a far pointer's address (Long: address, page): DE = the
; address, HL = the page (0 = plain memory). Page not 0: it must be a page
; this machine has and the address in the window, else mem_err BadPage.
mem_far:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			or h
			ret z
			call mem_chk
			ld a, d
			and #C0
			cp #40
			jr nz, mem_chk_bad
			ret

; PageOf(ptr): a far pointer's page
mem_pageof:
			ld hl, (mem_a1)
			inc hl
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ret

; Address(ptr): its page into the window (page 0: nothing); the address
mem_address:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

; HeapStart(), HeapEnd(): the heap region (CPCExpansion: the window, a D page at a time)
mem_heapstart:
			ld hl, (mem_hlo)
			ret
mem_heapend:
			ld hl, (mem_hhi)
			ret
; ProgramStart(), ProgramEnd() (the first byte after the program and its
; arrays), Top() (the platform's top of free RAM), StackTop() (the real stack)
mem_progstart:
			ld hl, ntc_start
			ret
mem_progend:
			ld hl, ntc_free
			ret
mem_top:
			jp ntc_plat_memtop
mem_stacktop:
			ld hl, (ntc_csp)
			ret

; mem_atend - Z when HL = mem_hhi (the heap region's end). Keeps BC, DE, HL.
mem_atend:
			ld a, (mem_hhi)
			cp l
			ret nz
			ld a, (mem_hhi + 1)
			cp h
			ret
; mem_fit - in the heap region (mem_hlo .. mem_hhi: a D page, or Small's main RAM): the first free block of mem_need
; bytes or more (free neighbours joined on the way), split when 4 or more
; bytes are left over, marked in use. Z: HL = its data. NZ: none.
mem_fit:
			ld hl, (mem_hlo)
mem_f_lp:
			call mem_atend
			jr z, mem_f_none
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 0, e
			jr z, mem_f_free
			res 0, e
mem_f_next:
			add hl, de
			jr mem_f_lp
mem_f_free:
			push hl
			add hl, de				; the block after
			call mem_atend
			jr z, mem_f_last
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 0, c
			jr nz, mem_f_last
			ld h, d					; free too: join them
			ld l, e
			add hl, bc
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_f_free
mem_f_last:
			pop hl
			push hl
			ex de, hl				; HL = its length, DE = the block
			ld bc, (mem_need)
			or a
			sbc hl, bc				; what is left over
			jr c, mem_f_small
			ld a, h
			or a
			jr nz, mem_f_cut
			ld a, l
			cp 4
			jr nc, mem_f_cut
			add hl, bc				; all of it
			ld b, h
			ld c, l
			pop hl
			jr mem_f_take
mem_f_cut:
			ex de, hl				; DE = left over, HL = the block
			pop hl
			push hl
			add hl, bc				; the free block after it
			ld (hl), e
			inc hl
			ld (hl), d
			pop hl
mem_f_take:
			ld a, c
			or 1					; in use
			ld (hl), a
			inc hl
			ld (hl), b
			inc hl
			xor a
			ret
mem_f_small:
			add hl, bc				; HL = its length again
			ex de, hl
			pop hl
			jr mem_f_next
mem_f_none:
			or 1					; NZ
			ret

; mem_big - in the heap region: join free neighbours, mem_max =
; the biggest free block's length if bigger
mem_big:
			ld hl, (mem_hlo)
mem_b_lp:
			call mem_atend
			ret z
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 0, e
			jr z, mem_b_free
			res 0, e
mem_b_next:
			add hl, de
			jr mem_b_lp
mem_b_free:
			push hl
			add hl, de
			call mem_atend
			jr z, mem_b_end
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 0, c
			jr nz, mem_b_end
			ld h, d
			ld l, e
			add hl, bc
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_b_free
mem_b_end:
			pop hl
			push hl
			ld hl, (mem_max)
			or a
			sbc hl, de
			pop hl
			jr nc, mem_b_next
			ld (mem_max), de
			jr mem_b_next

; ---- single bytes and words through far pointers (the window is put back)

; mem_at - mem_a1 = a far pointer's address: its page in, HL = the address
mem_at:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

mem_readbyte:
			call mem_at
			ld l, (hl)
			ld h, 0
			jr mem_putback
mem_readword:
			call mem_at
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jr mem_putback
mem_writebyte:
			call mem_at
			ld a, (mem_a2)
			ld (hl), a
			jr mem_putback
mem_writeword:
			call mem_at
			ld de, (mem_a2)
			ld (hl), e
			inc hl
			ld (hl), d
mem_putback:
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ret

;## ntc_mem ntc_memcore ntc_membank ntc_nxt_bank ntc_msx_bank ntc_dot_bank ntc_ep_bank @shared @far
; ------------------------------------------------------------
; ntc_mem (CPCExpansion) - 16K RAM pages in the #4000-#7FFF window (CPC gate
; array RAM setting: C0 = plain, C4-C7 + bank * 8 = page 0-3 of a 64K bank;
; the port's high byte #7F .. #78 picks the 512K block), up to a 4MB
; expansion: 64 banks, 257 pages (NTC_MEMBANKS: Option Memory's limit).
;   Page 1  = main RAM #4000-#7FFF (setting #C0)
;   Page 2+ = 4 pages for each bank the probe finds, the standard 512K
;             (port #7F) first, then the blocks on #7E .. #78
;   Page numbers are 16 bit (a far pointer's high word); 0 = plain memory.
;   No pages at all when the program (ntc_start .. ntc_free) or the
;   real stack is in the window: switching would hide them.
; Tables, made by the first call (mem_start) from ntc_free up, sized to
; what the probe finds (3 bytes a page); fewer pages when there isn't room
; below #4000 (or below the real stack):
;   the port table - 2 bytes a page: the BC that selects it (out (c), c),
;                    so selecting a page is a look-up, nothing worked out
;   the RAT        - 1 byte a page, its type: - free, C, D, I, U, B (the 4
;                    pages of a whole bank, AllocBank)
; No lists: a free page or bank is found by scanning the RAT (CPIR), a page
; is freed by writing - back. C / I / U pages come from the low block first
; (main + the #7F block), D pages from the high one (#78-#7E); each falls
; back to the other. On 576K or less every page is low.
; The page in the window is kept in mem_cur, written before the port,
; so an interrupt handler can always put the right page back.
; A new D page is one free block of #4000.
; ------------------------------------------------------------
MEM_BANKS	equ NTC_MEMBANKS	; 0 - 64
MEM_LB		equ 6			; the whole-bank kind (mem_kinds)

mem_count:		dw 0			; pages (0 = no paging)
mem_tport:		dw 0			; the port table (2 bytes a page: its BC)
mem_ttype:		dw 0			; the RAT (1 byte a page: its type)
mem_tend:		dw 0			; the first byte after them
mem_fp:			dw 0			; (making the port table: the next bank found)
mem_banks:		db 0			; 64K banks found
mem_tl:			db 0
mem_sw:			db 0			; mem_scan: 0 low, 1 high, 2 any
mem_kinds:		db "--CDIUB"		; the type character of each kind (0, 1 free)
mem_found:		ds MEM_BANKS + 1	; probe: the banks found (0-63), in order
mem_save:		ds MEM_BANKS + 1	; probe: the bytes the markers replace
mem_bksp:		dw 0			; CallBank: the real stack while bank code runs
mem_bkrmr:		db 0			; and the ROM / mode byte to put back

; mem_start - the first call: can this program page, what is fitted, the tables
mem_start:
			ld a, (mem_init)
			or a
			ret nz
			inc a
			ld (mem_init), a
			ld hl, ntc_free
			ld (mem_tend), hl
	IF NTC_WINHOLE
			jr mem_st_prog			; the program is built round the window (Option Reserve)
	ENDIF
	IF NTC_ROMLIB					; the keyword ROM: free RAM from #8000 on = built round it
			ld a, h
			cp #80
			jr nc, mem_st_prog
	ENDIF
			ld de, MEM_WIN + 1		; the program must be out of the window:
			or a					; it ends by #4000 ...
			sbc hl, de
			jr c, mem_st_prog
			ld hl, ntc_start		; ... or starts at #8000 or above
			ld de, #8000
			or a
			sbc hl, de
			ret c
mem_st_prog:
			ld hl, (ntc_csp)		; and the real stack too: at or below #4000,
			ld de, MEM_WIN + 1		; or 64 bytes or more above #8000
			or a
			sbc hl, de
			jr c, mem_probe
			ld hl, (ntc_csp)
			ld de, #8040
			or a
			sbc hl, de
			ret c
; the probe: interrupts off, nothing written until every byte is saved.
; Markers go in bank 63 down to bank 0, then main RAM, so a bank the
; hardware doesn't decode (a 6128 has one bank, a 512K expansion ignores
; the port's block bits) reads back a lower bank's marker, and a 64K
; machine (C4-C7 do nothing) reads main RAM's.
mem_probe:
		IF MEM_BANKS > 0
	IFDEF NTC_MSXDOS
			call msx_mem_probe		; MSX: the mapper's segments from MSX-DOS 2 (ntc_lib_msx.asm), sets mem_banks
	ELSE
	IFDEF NTC_EP128
			call ep_mem_probe		; the Enterprise: the segments taken from EXOS at the start (ntc_lib_ep.asm), sets mem_banks
	ELSE
	IFDEF NTC_ZXNDOTL
			call dot_mem_probe		; a Next dot command: pages from NextZXOS's allocator (ntc_lib_dot.asm), sets mem_banks
	ELSE
	IFNDEF NTC_ZXN
			ld a, i					; P/V = interrupts were on
			di
			push af
			ld bc, #7FC0
			out (c), c
			ld a, (MEM_WIN)
			ld (mem_save + MEM_BANKS), a
			ld hl, mem_save
			ld e, 0
mem_pr_save:
			call mem_jbc
			out (c), c
			ld a, (MEM_WIN)
			ld (hl), a
			inc hl
			inc e
			ld a, e
			cp MEM_BANKS
			jr nz, mem_pr_save
			ld e, MEM_BANKS
mem_pr_mark:
			dec e
			call mem_jbc
			out (c), c
			ld a, e
			add a, #40
			ld (MEM_WIN), a
			ld a, e
			or a
			jr nz, mem_pr_mark
			ld bc, #7FC0
			out (c), c
			ld a, #A5
			ld (MEM_WIN), a
			ld hl, mem_found
			ld d, 0
			ld e, 0
mem_pr_read:
			call mem_jbc
			out (c), c
			ld a, e
			add a, #40
			push hl
			ld hl, MEM_WIN
			cp (hl)
			pop hl
			jr nz, mem_pr_none
			ld (hl), e				; this bank is there
			inc hl
			inc d
mem_pr_none:
			inc e
			ld a, e
			cp MEM_BANKS
			jr nz, mem_pr_read
			ld hl, mem_save + MEM_BANKS	; put the bytes back, bank 63 down to 0
			ld e, MEM_BANKS
mem_pr_back:
			dec e
			dec hl
			call mem_jbc
			out (c), c
			ld a, (hl)
			ld (MEM_WIN), a
			ld a, e
			or a
			jr nz, mem_pr_back
			ld bc, #7FC0
			out (c), c
			ld a, (mem_save + MEM_BANKS)
			ld (MEM_WIN), a
			ld a, d
			ld (mem_banks), a
			pop af
			jp po, mem_pr_di
			ei
mem_pr_di:
	ELSE
			call nxt_mem_probe		; Next: the RAM probe (ntc_lib_nxt.asm), sets mem_banks
	ENDIF
	ENDIF
	ENDIF
	ENDIF
		ENDIF
			ld a, (mem_banks)		; pages = 1 + 4 a bank
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			inc hl
			ld (mem_count), hl
	IF NTC_WINHOLE
			call ntc_plat_memtop		; built round the window: the tables go above it
			jr mem_tb_lim			; (ntc_memtab), up to the platform's top
	ENDIF
	IF NTC_ROMLIB					; the keyword ROM: a program built round the window (it has no
			ld hl, ntc_free			; NTC_WINHOLE here) has its free RAM above it - up to the top
			ld a, h
			cp #80
			jr c, mem_tb_low
			call ntc_plat_memtop
			jr mem_tb_lim
mem_tb_low:
	ENDIF
			ld de, (ntc_csp)		; the tables must end by #4000, or 128 bytes
			ld hl, MEM_WIN			; under the real stack when it is lower
			or a
			sbc hl, de
			ld hl, MEM_WIN
			jr c, mem_tb_lim
			ld hl, -128
			add hl, de
mem_tb_lim:
			ld (mem_tend), hl		; the limit, for now
mem_tb_fit:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_tb_none
			ld d, h
			ld e, l
			add hl, hl
			add hl, de				; 3 bytes a page
	IF NTC_WINHOLE
			ld de, ntc_memtab
	ELSE
			ld de, ntc_free
	ENDIF
			add hl, de
			ex de, hl				; DE = their end
			ld hl, (mem_tend)
			or a
			sbc hl, de
			jr nc, mem_tb_ok
			ld hl, (mem_count)		; no room: one page fewer
			dec hl
			ld (mem_count), hl
			jr mem_tb_fit
mem_tb_none:
	IF NTC_WINHOLE
			ld hl, ntc_memtab
	ELSE
			ld hl, ntc_free
	ENDIF
			ld (mem_tend), hl
			ret
mem_tb_ok:
			ld (mem_tend), de
	IF NTC_WINHOLE
			ld hl, ntc_memtab
	ELSE
			ld hl, ntc_free
	ENDIF
			ld (mem_tport), hl
			ld de, (mem_count)
			add hl, de
			add hl, de
			ld (mem_ttype), hl
			ld bc, (mem_count)		; the RAT: every page free
			ld (hl), '-'
			dec bc
			ld a, b
			or c
			jr z, mem_tb_pl0
			ld d, h
			ld e, l
			inc de
			ldir
mem_tb_pl0:
	IFDEF NTC_PGLOADED
			ld hl, ntc_pgloaded		; Option Page ... Loaded n: those pages are taken (C), already
			ld b, (hl)				; filled - AllocPage never hands them out
			inc hl
mem_tb_pl:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			push hl
			ld hl, (mem_count)		; (past the pages there are: nothing to mark)
			or a
			sbc hl, de
			jr c, mem_tb_pl2
			ld hl, (mem_ttype)
			add hl, de
			dec hl
			ld (hl), 'C'
mem_tb_pl2:
			pop hl
			djnz mem_tb_pl
	ENDIF
	IFDEF NTC_EP128
			ld a, (ep_usable)		; the Enterprise: pages 2 .. usable + 1 are there (every free segment is a
			ld e, a					; page); the table is in fours, so the last four's leftovers are marked taken
			ld d, 0
			inc de
mem_tb_ep:
			ld hl, (mem_count)
			or a
			sbc hl, de
			jr z, mem_tb_epe
			jr c, mem_tb_epe
			inc de
			ld hl, (mem_ttype)
			add hl, de
			dec hl
			ld (hl), 'C'
			jr mem_tb_ep
mem_tb_epe:
	ENDIF
	IFDEF NTC_ZXN
			ld a, (zxn_usable)		; the Next: pages 2 .. usable + 1 are there; the table is in fours,
			ld e, a					; so the ones past that (the last four's leftovers) are marked taken
			ld d, 0
			inc de
mem_tb_zx:
			ld hl, (mem_count)
			or a
			sbc hl, de
			jr z, mem_tb_zxe
			jr c, mem_tb_zxe
			inc de
			ld hl, (mem_ttype)
			add hl, de
			dec hl
			ld (hl), 'C'
			jr mem_tb_zx
mem_tb_zxe:
	ENDIF
mem_tb_ports:						; the port table: page 1 main RAM, then 4 a bank found
	IF NTC_WINPAGED					; page 0 code under the window (Option Memory Paged): page 1, main
			ld hl, ntc_end			; RAM's own #4000-#7FFF, holds it - never handed out ('P')
			ld de, #4001
			or a
			sbc hl, de
			jr c, mem_tb_pt
			ld hl, (mem_ttype)
			ld (hl), 'P'
mem_tb_pt:
	ENDIF
			ld hl, (mem_tport)
			ld (hl), #C0
			inc hl
			ld (hl), #7F
			inc hl
			ld de, (mem_count)
			dec de					; DE = pages left
			ld bc, mem_found
			ld (mem_fp), bc
mem_tb_bk:
			ld a, d
			or e
			ret z
			push de
			ld bc, (mem_fp)
			ld a, (bc)
			inc bc
			ld (mem_fp), bc
			ld e, a
			call mem_jbc			; BC = its page 0's port (keeps DE, HL)
			pop de
			ld a, 4
mem_tb_pg:
			ld (hl), c
			inc hl
			ld (hl), b
			inc hl
			inc c
			dec de
			push af
			ld a, d
			or e
			jr z, mem_tb_pend		; (fewer pages than found: the rest left out)
			pop af
			dec a
			jr nz, mem_tb_pg
			jr mem_tb_bk
mem_tb_pend:
			pop af
			ret

; mem_jbc - E = bank 0-63: BC = the port for its page 0 (B = #7F - E / 8,
; C = #C4 + (E and 7) * 8). Keeps DE, HL.
mem_jbc:
	IFDEF NTC_MSXDOS
			jp msx_mem_jbc			; MSX: 64K bank E -> its page 0's setting (ntc_lib_msx.asm)
	ENDIF
	IFDEF NTC_EP128
			jp ep_mem_jbc			; the Enterprise: 64K bank E -> its page 0's setting (ntc_lib_ep.asm)
	ENDIF
	IFDEF NTC_ZXN
			jp nxt_mem_jbc			; Next: 64K bank E -> its first 16K Next bank (ntc_lib_nxt.asm)
	ENDIF
	IFDEF NTC_ZXNDOTL
			jp dot_mem_jbc			; a Next dot command: 64K bank E -> its page 0's setting (ntc_lib_dot.asm)
	ENDIF
			ld a, e
			rrca
			rrca
			rrca
			and 7
			ld b, a
			ld a, #7F
			sub b
			ld b, a
			ld a, e
			and 7
			add a, a
			add a, a
			add a, a
			add a, #C4
			ld c, a
			ret

; mem_sel - HL = page (valid): into the window. mem_cur first, then the
; port; nothing done when it is in already. Keeps BC, DE, HL.
mem_sel:
			push hl
			push de
			push bc
			ld de, (mem_cur)
			ld a, e
			cp l
			jr nz, mem_se_do
			ld a, d
			cp h
			jr z, mem_se_end
mem_se_do:
			ld (mem_cur), hl
			ld a, h
			or l
			ld bc, #7FC0			; (0: plain RAM)
			jr z, mem_se_out
			add hl, hl				; its port from the port table
			ld de, (mem_tport)
			add hl, de
			dec hl
			ld b, (hl)
			dec hl
			ld c, (hl)
mem_se_out:
	IFDEF NTC_MSXDOS
			jp msx_mem_se_out			; MSX: the segment into page 1 (PUT_P1: ntc_lib_msx.asm) -> mem_se_end
	ENDIF
	IFDEF NTC_EP128
			jp ep_mem_se_out			; the Enterprise: the segment into page 1 (port #B1: ntc_lib_ep.asm) -> mem_se_end
	ENDIF
	IFDEF NTC_ZXNDOTL
			jp dot_mem_se_out			; a Next dot command: the setting's two pages into slots 2, 3 (ntc_lib_dot.asm) -> mem_se_end
	ENDIF
	IFNDEF NTC_ZXN
			ld (ntc_rampt), bc
			out (c), c
	ELSE
			jp nxt_mem_se_out			; Next: window map via the MMU ports (ntc_lib_nxt.asm) -> mem_se_end
	ENDIF
mem_se_end:
			pop bc
			pop de
			pop hl
			ret

; mem_chk - HL = a page number: 1 .. mem_count, else mem_err BadPage.
; Keeps BC, DE, HL.
mem_chk:
			ld a, h
			or l
			jp z, mem_chk_bad
			push de
			push hl
			ex de, hl
			ld hl, (mem_count)
			or a
			sbc hl, de
			pop hl
			pop de
			ret nc
			jp mem_chk_bad
; ---- the tables (BC = a page)

; mem_tpb - HL = its type byte (in the RAT). Keeps A, BC, DE.
mem_tpb:
			ld hl, (mem_ttype)
			add hl, bc
			dec hl
			ret
; mem_push - A = a kind (mem_kinds: 2-6): the page is of that kind now. Keeps A, BC, DE.
mem_push:
			push af
			push de
			ld e, a
			ld d, 0
			ld hl, mem_kinds
			add hl, de
			ld a, (hl)
			call mem_tpb
			ld (hl), a
			pop de
			pop af
			ret
; mem_remove - (A = a kind) nothing to take it off: the RAT has no lists. NZ. Keeps BC, DE.
mem_remove:
			ld a, 1
			or a
			ret
; mem_lowhigh - A = the block the page is in: 0 low (main, or the #7F
; block) or 1 high. Keeps BC, DE.
mem_lowhigh:
			push de
			ld h, b
			ld l, c
			add hl, hl
			ld de, (mem_tport)
			add hl, de
			dec hl					; its port's high byte
			ld a, (hl)
			pop de
			cp #7F
			ld a, 0
			ret z
			inc a
			ret
; mem_tofree - the page free again. Keeps BC, DE.
mem_tofree:
			call mem_tpb
			ld (hl), '-'
			ret
; mem_scan - A = 0 low, 1 high, 2 either: BC = the first free page in it, NZ;
; Z = none
mem_scan:
			ld (mem_sw), a
			ld hl, (mem_ttype)
			ld bc, (mem_count)
mem_sc_lp:
			ld a, b
			or c
			ret z
			ld a, '-'
			cpir
			jr nz, mem_sc_none
			push bc
			push hl
			ld de, (mem_ttype)
			or a
			sbc hl, de				; the page: its entry is at HL - 1
			ld b, h
			ld c, l
			ld a, (mem_sw)
			cp 2
			jr z, mem_sc_hit
			call mem_lowhigh
			ld hl, mem_sw
			cp (hl)
			jr z, mem_sc_hit
			pop hl
			pop bc
			jr mem_sc_lp
mem_sc_hit:
			pop af
			pop af
			ld a, 1
			or a
			ret
mem_sc_none:
			xor a
			ret
; mem_dnext - BC = a page (0: before the first): BC = the next D page, NZ;
; Z = none
mem_dnext:
			ld hl, (mem_count)
			or a
			sbc hl, bc
			ret z
			push hl
			ld hl, (mem_ttype)
			add hl, bc
			pop bc
			ld a, 'D'
			cpir
			jr nz, mem_sc_none
			ld de, (mem_ttype)
			or a
			sbc hl, de
			ld b, h
			ld c, l
			ld a, 1
			or a
			ret
; mem_listof - A = the page's kind (2-6), or its free block (0, 1). Keeps BC, DE.
mem_listof:
			call mem_tpb
			ld a, (hl)
			push bc
			ld hl, mem_kinds + 2
			ld b, 5
			ld c, 2
mem_lo_lp:
			cp (hl)
			jr z, mem_lo_got
			inc hl
			inc c
			djnz mem_lo_lp
			pop bc
			jp mem_lowhigh
mem_lo_got:
			ld a, c
			pop bc
			ret
; mem_kindlist - A = a type character: A = its kind (2-5), NZ; Z = not one.
mem_kindlist:
			ld hl, mem_kinds + 2
			ld b, 4
			ld c, 2
mem_kl_lp:
			cp (hl)
			jr z, mem_kl_got
			inc hl
			inc c
			djnz mem_kl_lp
			xor a
			ret
mem_kl_got:
			ld a, c
			or a
			ret
; mem_take - A = a kind (2-5): a free page of that kind now - D from the
; high block first, the others from the low one - a D page made one free
; block. BC = the page, NZ; Z = none left.
mem_take:
			ld (mem_tl), a
			cp 3
			ld a, 1
			jr z, mem_tk_s
			xor a
mem_tk_s:
			call mem_scan
			jr nz, mem_tk_got
			ld a, 2
			call mem_scan
			ret z
mem_tk_got:
			ld a, (mem_tl)
			call mem_push
			cp 3
			jr nz, mem_tk_done
			ld h, b
			ld l, c
			call mem_sel
			ld hl, #4000
			ld (MEM_WIN), hl
			ld hl, (mem_keep)
			call mem_sel
mem_tk_done:
			ld a, 1
			or a
			ret

; ---- what's there

; Pages(): pages (0 = no paging, 1 = 64K, 5 = 128K ... 33 = 512K ... 257 = 4MB)
mem_pages:
			ld hl, (mem_count)
			ret

; FreePages(): the free pages (- in the RAT)
mem_freepages:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			ld b, h
			ld c, l
			ld hl, (mem_ttype)
			ld de, 0
mem_fp_lp:
			ld a, '-'
			cpir
			jr nz, mem_fp_end
			inc de
			ld a, b
			or c
			jr nz, mem_fp_lp
mem_fp_end:
			ex de, hl
			ret

; RamSize(): K of RAM the probe found (64 + 64 a bank), 0 = not probed
mem_ramsize:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
	IFDEF NTC_EP128
			ld a, (EPB_NSEG)		; the Enterprise: every segment is 16K - the free ones taken at the start,
			add a, 5				; the program's three, the screen's and EXOS's own
			ld l, a
			ld h, 0
			jr nc, mem_rs_ep
			inc h
mem_rs_ep:
			add hl, hl				; x 16
			add hl, hl
			add hl, hl
			add hl, hl
			ret
	ENDIF
			ld a, (mem_banks)
			ld l, a
			ld h, 0
			inc hl
			add hl, hl				; x 64
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ret

; Model(): 0 none, 1 small (1 page), 2 medium (up to 5), 3 large (up to
; 33, a 512K expansion), 4 huge (more)
mem_model:
			ld de, (mem_count)
			ld hl, 0
			ld a, d
			or a
			jr nz, mem_md_huge
			ld a, e
			or a
			ret z
			inc l
			cp 2
			ret c
			inc l
			cp 6
			ret c
			inc l
			cp 34
			ret c
mem_md_huge:
			ld l, 4
			ret

; TableEnd(): the first byte after Memory's tables (they start at the program's end)
mem_tableend:
			ld hl, (mem_tend)
			ret

; PageType(page): its type character
mem_pagetype:
			ld hl, (mem_a1)
			call mem_chk
			ld b, h
			ld c, l
			call mem_tpb
			ld l, (hl)
			ld h, 0
			ret

; Map(first, count): one character per page from first, into the string
; result (as many as fit; pages past the last are left out)
mem_map:
			ld hl, (mem_res)
			dec hl
			ld a, (hl)				; the string's capacity
			inc hl
			ld (mem_srca), hl
			ld (mem_chunk), a
			ld bc, (mem_a1)
			ld hl, (mem_a2)
			ld (mem_left), hl
mem_mp_lp:
			ld hl, (mem_left)
			bit 7, h
			jr nz, mem_mp_end
			ld a, h
			or l
			jr z, mem_mp_end
			ld a, b
			or c
			jr z, mem_mp_end
			ld hl, (mem_count)
			or a
			sbc hl, bc
			jr c, mem_mp_end
			ld a, (mem_chunk)
			or a
			jr z, mem_mp_end
			dec a
			ld (mem_chunk), a
			call mem_tpb
			ld a, (hl)
			ld hl, (mem_srca)
			ld (hl), a
			inc hl
			ld (mem_srca), hl
			inc bc
			ld hl, (mem_left)
			dec hl
			ld (mem_left), hl
			jr mem_mp_lp
mem_mp_end:
			ld hl, (mem_srca)
			ld (hl), 0
			ret

; ---- whole pages

; AllocPage(kind): a free page, now of that kind (C, D, I, U); 0 = none left
mem_allocpage:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_ap_none
			ld hl, (mem_a1)
			ld a, h
			or a
			jr nz, mem_ap_none
			ld a, l
			call mem_kindlist
			jr z, mem_ap_none
			call mem_take
			jr z, mem_ap_none
			ld h, b
			ld l, c
			ret
mem_ap_none:
			ld hl, 0
			ret

; FreePage(page): back to free (a D page's blocks go with it). OK, or
; BadPage (not a page, or free already)
mem_freepage:
			ld hl, (mem_a1)
			call mem_chk
			ld b, h
			ld c, l
			call mem_listof
			cp 2
			jp c, mem_chk_bad
			call mem_remove
			call mem_tofree
			ld hl, 0
			ret

; SelectPage(page): into the window; #4000
mem_selpage:
			ld hl, (mem_a1)
			call mem_chk
			call mem_sel
			ld hl, MEM_WIN
			ret

; CurrentPage(): the page in the window (0 = no paging)
mem_curpage:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			ld hl, (mem_cur)
			ret

; ---- whole 64K banks (page numbers 4 * bank - 2 .. 4 * bank + 1)

; Banks(): whole banks the tables cover (0 = none)
mem_bankcount:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
	IFDEF NTC_EP128
			ld a, (ep_usable)		; the Enterprise: whole banks only (the last four pages may not all be there)
			srl a
			srl a
			ld l, a
			ld h, 0
			ret
	ENDIF
			dec hl
			srl h
			rr l
			srl h
			rr l
			ret

; mem_bkfirst - (mem_a1) = a bank, 1 .. Banks(): BC = its first page, else
; mem_err BadPage
mem_bkfirst:
			call mem_bankcount
			ld de, (mem_a1)
			ld a, d
			or e
			jp z, mem_chk_bad
			or a
			sbc hl, de
			jp c, mem_chk_bad
			ex de, hl
			dec hl
			add hl, hl
			add hl, hl
			inc hl
			inc hl
			ld b, h
			ld c, l
			ret

; AllocBank(): a bank whose 4 pages are all free, now type B; 0 = none
mem_allocbank:
			call mem_bankcount
			ld a, l
			or a
			jr z, mem_ab_none
			ld (mem_tl), a			; banks left to try
			ld bc, 2
mem_ab_lp:
			push bc
			ld d, 4
mem_ab_chk:
			call mem_listof
			cp 2
			jr nc, mem_ab_used
			inc bc
			dec d
			jr nz, mem_ab_chk
			pop bc					; all 4 free: onto the bank list
			push bc
			ld d, 4
mem_ab_take:
			call mem_listof
			call mem_remove
			ld a, MEM_LB
			call mem_push
			inc bc
			dec d
			jr nz, mem_ab_take
			pop hl					; bank = (first page + 2) / 4
			inc hl
			inc hl
			srl h
			rr l
			srl h
			rr l
			ret
mem_ab_used:
			pop bc
			ld hl, 4
			add hl, bc
			ld b, h
			ld c, l
			ld a, (mem_tl)
			dec a
			ld (mem_tl), a
			jr nz, mem_ab_lp
mem_ab_none:
			ld hl, 0
			ret

; FreeBank(bank): its 4 pages back to free. OK, or BadPage (not a bank,
; or not taken with AllocBank)
mem_bkstub:
			ld hl, ntc_bk_stub
			ret

mem_freebank:
			call mem_bkfirst
			push bc
			ld d, 4
mem_fb_chk:
			call mem_listof
			cp MEM_LB
			jp nz, mem_chk_bad
			inc bc
			dec d
			jr nz, mem_fb_chk
			pop bc
			ld d, 4
mem_fb_lp:
			ld a, MEM_LB
			call mem_remove
			call mem_tofree
			inc bc
			dec d
			jr nz, mem_fb_lp
			ld hl, 0
			ret

; CallBank(bank, address, value): runs the bank's code at address with the
; whole 64K being that bank (RAM setting C2), HL = value; its HL comes back.
; The bank must be taken (AllocBank). The switch code (ntc_bk_stub, about
; 20 bytes) is copied into the bank at its own address first, so those
; bytes of the bank are overwritten. Interrupts are off and both ROMs are
; off while the bank code runs; it starts with the stack at the bank's top
; (#FFFF down) and ends with ret. It must keep the alternate registers.
mem_callbank:
			call mem_bkfirst
			call mem_listof
			cp MEM_LB
			jp nz, mem_chk_bad
			ld hl, ntc_bk_stub		; copy the switch code into the bank
mem_cb_cp:
			push bc
			ld a, h					; its page in the bank: address / #4000
			rlca
			rlca
			and 3
			add a, c
			ld c, a
			jr nc, mem_cb_nc
			inc b
mem_cb_nc:
			push hl
			ld h, b
			ld l, c
			call mem_sel
			pop hl
			ld b, (hl)
			ld a, h
			and #3F
			or #40
			ld d, a
			ld e, l
			ld a, b
			ld (de), a
			pop bc
			inc hl
			ld a, l
			cp low ntc_bk_end
			jr nz, mem_cb_cp
			ld a, h
			cp high ntc_bk_end
			jr nz, mem_cb_cp
			ld hl, (mem_keep)
			call mem_sel
			call mem_bkfirst		; BC = C2 for the bank: its page 0's port
			ld h, b					; ((#C4 + bank bits) and #F8, or 2)
			ld l, c
			add hl, hl
			ld de, (mem_tport)
			add hl, de
			dec hl
			ld b, (hl)
			dec hl
			ld a, (hl)
			and #F8
			or 2
			ld c, a
			ld de, (mem_a2)
			ld hl, (mem_a3)
			jp ntc_bk_go

; ---- heap in D pages

; Alloc(size): a far pointer to size bytes in a D page, 0 = no room.
; Tries the page in the window, then the other D pages, then takes a free
; page. The window is left as it was.
mem_alloc:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_al_fail
			ld hl, (mem_a1)
			ld a, h
			or l
			jr nz, mem_al_size
			inc hl
mem_al_size:
			ld de, #3FFF			; up to #3FFE: a page less its header
			or a
			push hl
			sbc hl, de
			pop hl
			jr nc, mem_al_fail
			inc hl
			inc hl
			inc hl
			res 0, l				; (with its header, made even)
			ld (mem_need), hl
			ld bc, (mem_keep)
			call mem_tpb
			ld a, (hl)
			cp 'D'
			jr nz, mem_al_scan
			ld h, b
			ld l, c
			call mem_try
			jr z, mem_al_got
mem_al_scan:
			ld bc, 0
mem_al_lp:
			call mem_dnext
			jr z, mem_al_new
			ld hl, (mem_keep)
			or a
			sbc hl, bc
			jr z, mem_al_lp
			push bc
			ld h, b
			ld l, c
			call mem_try
			pop bc
			jr z, mem_al_got
			jr mem_al_lp
mem_al_new:
			ld a, 3
			call mem_take
			jr z, mem_al_back
			ld h, b
			ld l, c
			call mem_try
mem_al_got:
			ld de, (mem_cur)		; HL = the data, its page is in
			ld (mem_hi), de
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ret
mem_al_back:
			ld hl, (mem_keep)
			call mem_sel
mem_al_fail:
			ld hl, 0
			ld (mem_hi), hl
			ret

; mem_try - HL = a D page: select it, then mem_fit
mem_try:
			call mem_sel
			jp mem_fit

; Free(ptr): a block Alloc gave back. A page with nothing left in use
; goes back to free. OK, or BadPage (not a block in use in a D page)
mem_free:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			jp z, mem_chk_bad
			ld b, h
			ld c, l
			call mem_tpb
			ld a, (hl)
			cp 'D'
			jp nz, mem_chk_bad
			ld h, b
			ld l, c
			call mem_sel
			ex de, hl
			dec hl
			dec hl
			bit 0, (hl)
			jr z, mem_err_page
			res 0, (hl)
			ld hl, #4000			; is the whole page free now?
			ld (mem_need), hl
			push bc
			call mem_fit			; only a page with every block free fits
			pop bc
			jr nz, mem_fr_done
			ld a, 3
			call mem_remove
			call mem_tofree
mem_fr_done:
			ld hl, (mem_keep)
			call mem_sel
			ld hl, 0
			ret
mem_err_page:
			ld hl, (mem_keep)
			call mem_sel
			jp mem_chk_bad

; Largest(): the biggest block Alloc could give now
mem_largest:
			ld hl, 0
			ld (mem_max), hl
			call mem_freepages		; a free page: a whole page
			ld a, h
			or l
			ld hl, #3FFE
			ret nz
			ld bc, 0
mem_lg_lp:
			call mem_dnext
			jr z, mem_lg_end
			ld h, b
			ld l, c
			call mem_sel
			push bc
			call mem_big
			pop bc
			jr mem_lg_lp
mem_lg_end:
			ld hl, (mem_keep)
			call mem_sel
			ld hl, (mem_max)
			ld a, h
			or l
			ret z
			dec hl
			dec hl
			ret

;## ntc_membank ntc_plat_rmr @shared @romram
; ------------------------------------------------------------
; ntc_membank - Memory's CallBank switch (CPCExpansion). Runs from RAM
; (a keyword ROM can't be seen once both ROMs are off). BC = the C2
; setting and port for the bank, DE = the address in the bank, HL = value.
; ntc_bk_stub .. ntc_bk_end is also copied into the bank at the same
; address: each out is followed by the next byte from the other 64K.
; ------------------------------------------------------------
ntc_bk_go:
			ld a, i					; P/V = interrupts were on
			di
			push af
			ld (mem_bksp), sp
			call ntc_plat_rmr
			ld (mem_bkrmr), a
			or #0C					; both ROMs off
			push bc
			ld b, #7F
			out (c), a
			pop bc
ntc_bk_stub:
			out (c), c				; the bank is all 64K now
			ld sp, 0
			ld bc, ntc_bk_ret
			push bc
			push de
			ret						; to the bank's code, HL = value
ntc_bk_ret:
			ld bc, #7FC0
			out (c), c				; main RAM again
ntc_bk_end:
			ld sp, (mem_bksp)
			ld a, (mem_bkrmr)
			ld b, #7F
			out (c), a				; the ROMs as they were
			ld bc, (ntc_rampt)
			out (c), c				; and the window's page
			pop af
			jp po, ntc_bk_di
			ei
ntc_bk_di:
			ret

;## ntc_list ntc_memcore @shared @far
; ------------------------------------------------------------
; ntc_list - the List class: linked lists in the Memory class's heap (D
; pages with CPCExpansion, main RAM with Small), handles and nodes are far
; pointers (Longs: address, page). Nodes come from pools: a list takes a
; block of up to 16000 bytes at a time and cuts it into nodes on its free
; chain, so getting / giving back a node is a pointer swap.
;   header (20 bytes): +0 first, +4 last, +8 count, +10 data bytes a node,
;                      +12 free chain, +16 pools
;   pool:  +0 the next pool, then nodes
;   node:  +0 next, +4 previous, +8 the data
; Runs through mem_go like the Memory class (real stack); the window is
; put back at the end.
; ------------------------------------------------------------
LST_FIRST	equ 0
LST_LAST	equ 4
LST_COUNT	equ 8
LST_SIZE	equ 10
LST_FREE	equ 12
LST_POOLS	equ 16
LST_HDR		equ 20
LST_NEXT	equ 0
LST_PREV	equ 4
LST_DATA	equ 8

lst_h:			ds 4			; the list's header
lst_n:			ds 4			; nodes, far pointers (address, page)
lst_m:			ds 4
lst_k:			ds 4
lst_p:			ds 4
lst_q:			ds 4
lst_s1:			ds 4
lst_s2:			ds 4
lst_size:		dw 0
lst_v:			dw 0
lst_cnt:		dw 0
lst_key:		dw 0

; lst_at - HL = a far pointer variable: its page in, HL = its address
lst_at:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			or h
			call nz, mem_sel
			ex de, hl
			ret
; lst_rd - HL = far variable, DE = offset: HL = the word there
lst_rd:
			push de
			call lst_at
			pop de
			add hl, de
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ret
; lst_wr - HL = far variable, DE = offset, BC = the word to write there
lst_wr:
			push bc
			push de
			call lst_at
			pop de
			add hl, de
			pop bc
			ld (hl), c
			inc hl
			ld (hl), b
			ret
; lst_rd4 - HL = far variable, DE = offset, BC = a variable: the far pointer there into it
lst_rd4:
			push bc
			push de
			call lst_at
			pop de
			add hl, de
			pop de
			ld bc, 4
			ldir
			ret
; lst_wr4 - HL = far variable, DE = offset, BC = a variable: it goes into the field
lst_wr4:
			push bc
			push de
			call lst_at
			pop de
			add hl, de
			ex de, hl
			pop hl
			ld bc, 4
			ldir
			ret
; lst_null - HL = far variable: Z when it is 0
lst_null:
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ret
; lst_cp4 - HL = from, DE = to (variables)
lst_cp4:
			ld bc, 4
			ldir
			ret
; lst_zero - HL = a variable: 0
lst_zero:
			xor a
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret
; lst_arg - HL = a Long argument's address, DE = a variable: copied, checked
; (not 0, a page this machine has, an address in the window) else BadPage
lst_arg:
			push hl
			push de
			call lst_cp4
			pop hl
			call lst_null
			jp z, mem_chk_bad
			pop hl
			jp mem_far
; lst_back - the window as it was; lst_retn / lst_ret0 - the result (Long)
lst_back:
			ld hl, (mem_keep)
			jp mem_sel
lst_retn:
			call lst_back
			ld hl, (lst_n + 2)
			ld (mem_hi), hl
			ld hl, (lst_n)
			ret
lst_ret0:
			call lst_back
			ld hl, 0
			ld (mem_hi), hl
			ret
; lst_count - A = 1 / -1: the header's count + A
lst_count:
			push af
			ld hl, lst_h
			ld de, LST_COUNT
			call lst_rd
			pop af
			ld b, h
			ld c, l
			inc bc
			dec a
			jr z, lst_ct_up
			dec bc
			dec bc
lst_ct_up:
			ld hl, lst_h
			ld de, LST_COUNT
			jp lst_wr

; lst_newnode - a node from lst_h's free chain (a new pool when it is empty),
; cleared, in lst_n. NZ; Z = no room
lst_newnode:
			ld hl, lst_h
			ld de, LST_FREE
			ld bc, lst_n
			call lst_rd4
			ld hl, lst_n
			call lst_null
			jp nz, lst_nn_take
			ld hl, lst_h			; a new pool: as many nodes as fit in 16000 bytes
			ld de, LST_SIZE
			call lst_rd
			ld de, LST_DATA
			add hl, de
			ld (lst_v), hl			; node size
			ex de, hl
			ld hl, 15996
			ld bc, 0
lst_nn_div:
			or a
			sbc hl, de
			jr c, lst_nn_n
			inc bc
			jr lst_nn_div
lst_nn_n:
			ld (lst_cnt), bc
			ld hl, 4
			ld de, (lst_v)
lst_nn_mul:
			add hl, de
			dec bc
			ld a, b
			or c
			jr nz, lst_nn_mul
			ld (mem_a1), hl
			call mem_alloc
			ld a, h
			or l
			ret z
			ld (lst_m), hl			; the pool
			ld hl, (mem_hi)
			ld (lst_m + 2), hl
			ld hl, lst_h			; pool.next = the pools so far, pools = it
			ld de, LST_POOLS
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_m
			ld de, 0
			ld bc, lst_k
			call lst_wr4
			ld hl, lst_h
			ld de, LST_POOLS
			ld bc, lst_m
			call lst_wr4
			ld hl, lst_m			; its nodes, each pointing at the next
			call lst_at
			ld de, 4
			add hl, de
			push hl
			ld bc, (lst_cnt)
lst_nn_link:
			dec bc
			ld a, b
			or c
			jr z, lst_nn_last
			push bc
			ld d, h
			ld e, l
			ld bc, (lst_v)
			ex de, hl
			add hl, bc
			ex de, hl				; DE = the next node
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld a, (lst_m + 2)
			ld (hl), a
			inc hl
			ld a, (lst_m + 3)
			ld (hl), a
			ex de, hl
			pop bc
			jr lst_nn_link
lst_nn_last:
			call lst_zero
			pop hl
			ld (lst_n), hl
			ld hl, (lst_m + 2)
			ld (lst_n + 2), hl
lst_nn_take:
			ld hl, lst_n			; the free chain goes on from its next
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_h
			ld de, LST_FREE
			ld bc, lst_k
			call lst_wr4
			ld hl, lst_h			; cleared: next, previous, data
			ld de, LST_SIZE
			call lst_rd
			ld de, LST_DATA - 1
			add hl, de
			push hl
			ld hl, lst_n
			call lst_at
			pop bc
			ld (hl), 0
			ld d, h
			ld e, l
			inc de
			ldir
			ld a, 1
			or a
			ret

; Create(size): a new empty list of nodes with size data bytes; 0 = no room
lst_create:
			ld hl, (mem_a1)
			ld (lst_size), hl
			ld de, 15988 + 1
			or a
			sbc hl, de
			jp nc, lst_ret0
			ld hl, LST_HDR
			ld (mem_a1), hl
			call mem_alloc
			ld a, h
			or l
			jp z, lst_ret0
			ld (lst_n), hl
			ld hl, (mem_hi)
			ld (lst_n + 2), hl
			ld hl, lst_n
			call lst_at
			ld b, LST_HDR
lst_cr_clr:
			ld (hl), 0
			inc hl
			djnz lst_cr_clr
			ld hl, lst_n
			ld de, LST_SIZE
			ld bc, (lst_size)
			call lst_wr
			jp lst_retn

; Append(h) / Prepend(h): a new node at the end / the start; 0 = no room
lst_append:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			call lst_newnode
			jp z, lst_ret0
			ld hl, lst_h			; node.prev = last
			ld de, LST_LAST
			ld bc, lst_m
			call lst_rd4
			ld hl, lst_n
			ld de, LST_PREV
			ld bc, lst_m
			call lst_wr4
			ld hl, lst_m
			call lst_null
			ld hl, lst_h
			ld de, LST_FIRST
			jr z, lst_ap_link		; empty: it is the first too
			ld hl, lst_m
			ld de, LST_NEXT
lst_ap_link:
			ld bc, lst_n
			call lst_wr4
			ld hl, lst_h
			ld de, LST_LAST
			ld bc, lst_n
			call lst_wr4
lst_added:
			ld a, 1
			call lst_count
			jp lst_retn

lst_prepend:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			call lst_newnode
			jp z, lst_ret0
			ld hl, lst_h			; node.next = first
			ld de, LST_FIRST
			ld bc, lst_m
			call lst_rd4
			ld hl, lst_n
			ld de, LST_NEXT
			ld bc, lst_m
			call lst_wr4
			ld hl, lst_m
			call lst_null
			ld hl, lst_h
			ld de, LST_LAST
			jr z, lst_pp_link		; empty: it is the last too
			ld hl, lst_m
			ld de, LST_PREV
lst_pp_link:
			ld bc, lst_n
			call lst_wr4
			ld hl, lst_h
			ld de, LST_FIRST
			ld bc, lst_n
			call lst_wr4
			jp lst_added

; InsertAfter(h, node): a new node after that one (node 0: at the start)
lst_insert:
			ld hl, (mem_a2)
			call lst_null
			jp z, lst_prepend
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, (mem_a2)
			ld de, lst_m
			call lst_arg
			call lst_newnode
			jp z, lst_ret0
			ld hl, lst_m			; k = m.next
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_n			; n.prev = m, n.next = k, m.next = n
			ld de, LST_PREV
			ld bc, lst_m
			call lst_wr4
			ld hl, lst_n
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_wr4
			ld hl, lst_m
			ld de, LST_NEXT
			ld bc, lst_n
			call lst_wr4
			ld hl, lst_k			; k.prev = n, or last = n
			call lst_null
			ld hl, lst_h
			ld de, LST_LAST
			jr z, lst_in_link
			ld hl, lst_k
			ld de, LST_PREV
lst_in_link:
			ld bc, lst_n
			call lst_wr4
			jp lst_added

; Delete(h, node): out of the list, back on its free chain. OK
lst_delete:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, (mem_a2)
			ld de, lst_n
			call lst_arg
			ld hl, lst_n
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_n
			ld de, LST_PREV
			ld bc, lst_m
			call lst_rd4
			call lst_unlink
			ld a, -1
			call lst_count
			ld hl, lst_h			; node.next = the free chain, free = node
			ld de, LST_FREE
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_n
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_wr4
			ld hl, lst_h
			ld de, LST_FREE
			ld bc, lst_n
			call lst_wr4
			call lst_back
			ld hl, 0
			ret
; lst_unlink - lst_m (previous) and lst_k (next) of a node: joined; the header's first / last
lst_unlink:
			ld hl, lst_m
			call lst_null
			ld hl, lst_h
			ld de, LST_FIRST
			jr z, lst_ul_1
			ld hl, lst_m
			ld de, LST_NEXT
lst_ul_1:
			ld bc, lst_k
			call lst_wr4
			ld hl, lst_k
			call lst_null
			ld hl, lst_h
			ld de, LST_LAST
			jr z, lst_ul_2
			ld hl, lst_k
			ld de, LST_PREV
lst_ul_2:
			ld bc, lst_m
			jp lst_wr4

; First(h), Last(h): a node or 0. NextOf(node), PrevOf(node): a node or 0
lst_first:
			ld de, LST_FIRST
			jr lst_field
lst_last:
			ld de, LST_LAST
lst_field:
			push de
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			pop de
			ld hl, lst_h
			ld bc, lst_n
			call lst_rd4
			jp lst_retn
lst_nextof:
			ld de, LST_NEXT
			jr lst_field
lst_prevof:
			ld de, LST_PREV
			jr lst_field

; Count(h): nodes in the list
lst_countof:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, lst_h
			ld de, LST_COUNT
			call lst_rd
lst_rethl:
			push hl
			call lst_back
			pop hl
			ret

; GetWord(node, offset), GetByte(node, offset): from its data
lst_getword:
			call lst_data
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp lst_rethl
lst_getbyte:
			call lst_data
			ld l, (hl)
			ld h, 0
			jp lst_rethl
; SetWord node, offset, value / SetByte node, offset, value
lst_setword:
			call lst_data
			ld de, (mem_a3)
			ld (hl), e
			inc hl
			ld (hl), d
			jp lst_back
lst_setbyte:
			call lst_data
			ld a, (mem_a3)
			ld (hl), a
			jp lst_back
; lst_data - mem_a1 = a node's address (Long), mem_a2 = offset: its page in, HL = the byte
lst_data:
			ld hl, (mem_a1)
			ld de, lst_n
			call lst_arg
			ld hl, lst_n
			call lst_at
			ld de, LST_DATA
			add hl, de
			ld de, (mem_a2)
			add hl, de
			ret
; Data(node): a far pointer to its data (for Memory.Copy, ReadWord ...)
lst_dataof:
			ld hl, (mem_a1)
			ld de, lst_n
			call lst_arg
			ld hl, (lst_n)
			ld de, LST_DATA
			add hl, de
			ld (lst_n), hl
			jp lst_retn

; Search(h, offset, value): the first node whose word at offset is value, or 0
lst_search:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, lst_h
			ld de, LST_FIRST
			ld bc, lst_n
			call lst_rd4
lst_se_lp:
			ld hl, lst_n
			call lst_null
			jp z, lst_ret0
			ld hl, (mem_a2)
			ld de, LST_DATA
			add hl, de
			ex de, hl
			ld hl, lst_n
			call lst_rd
			ld de, (mem_a3)
			or a
			sbc hl, de
			jp z, lst_retn
			ld hl, lst_n
			ld de, LST_NEXT
			ld bc, lst_n
			call lst_rd4
			jr lst_se_lp

; Destroy(h): its pools and header back to the heap. OK
lst_destroy:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, lst_h
			ld de, LST_POOLS
			ld bc, lst_n
			call lst_rd4
lst_ds_lp:
			ld hl, lst_n
			call lst_null
			jr z, lst_ds_hdr
			ld hl, lst_n
			ld de, 0
			ld bc, lst_k
			call lst_rd4
			ld hl, lst_n
			ld (mem_a1), hl
			call mem_free
			ld hl, lst_k
			ld de, lst_n
			call lst_cp4
			jr lst_ds_lp
lst_ds_hdr:
			ld hl, lst_h
			ld (mem_a1), hl
			call mem_free
			call lst_back
			ld hl, 0
			ret

;## ntc_listsort ntc_list ntc_buf2k @shared @far
; Sort(h, offset): in order of the (signed) word at offset in each node's
; data, equal ones keeping their order. A radix sort: two passes over the
; list (the key's low byte, then its high byte with the sign bit flipped),
; each node going onto the end of one of 256 buckets, the buckets joined
; in order after each pass; then the previous links. The bucket heads and
; tails (far pointers) fill the 2K buffer (ntc_buf).
LST_HEADS	equ ntc_buf
LST_TAILS	equ ntc_buf + 1024
			ASSERT NTC_BUFSIZE >= 2048, "List.Sort needs the whole 2K buffer (Option Buffer's size)"

lst_ko:			dw 0			; the key's offset in a node
lst_byte:		db 0			; 0: the low byte, 1: the high byte
lst_bp:			dw 0
lst_cpg:		dw 0			; the page in the window (0: not known)

; lst_rs_sel - DE = a page (0: main memory, nothing to do): in the window.
; Keeps HL.
lst_rs_sel:
			ld a, d
			or e
			ret z
			ld a, (lst_cpg)
			cp e
			jr nz, lst_rs_sdo
			ld a, (lst_cpg + 1)
			cp d
			ret z
lst_rs_sdo:
			ld (lst_cpg), de
			push hl
			ex de, hl
			call mem_sel
			pop hl
			ret

lst_sort:
			ld hl, (mem_a1)
			ld de, lst_h
			call lst_arg
			ld hl, (mem_a2)
			ld de, LST_DATA
			add hl, de
			ld (lst_ko), hl
			xor a
			ld (lst_byte), a
			call lst_rs_pass
			ld a, 1
			ld (lst_byte), a
			call lst_rs_pass
			ld hl, lst_s2			; the previous links, and the last node
			call lst_zero
			ld hl, lst_h
			ld de, LST_FIRST
			ld bc, lst_n
			call lst_rd4
			ld hl, 0
			ld (lst_cpg), hl
lst_rs_fix:
			ld hl, (lst_n)
			ld a, h
			or l
			jr z, lst_rs_fixed
			ld de, (lst_n + 2)
			call lst_rs_sel
			ld e, (hl)				; k = its next
			inc hl
			ld d, (hl)
			inc hl
			ld (lst_k), de
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld (lst_k + 2), de
			ld de, (lst_s2)			; its previous = s2
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld de, (lst_s2 + 2)
			ld (hl), e
			inc hl
			ld (hl), d
			ld hl, (lst_n)			; s2 = the node, on to the next
			ld (lst_s2), hl
			ld hl, (lst_n + 2)
			ld (lst_s2 + 2), hl
			ld hl, (lst_k)
			ld (lst_n), hl
			ld hl, (lst_k + 2)
			ld (lst_n + 2), hl
			jr lst_rs_fix
lst_rs_fixed:
			ld hl, lst_h
			ld de, LST_LAST
			ld bc, lst_s2
			call lst_wr4
			call lst_back
			ld hl, 0
			ret

; one pass: every node onto its bucket's end, then the buckets joined
lst_rs_pass:
			ld hl, ntc_buf
			ld (hl), 0
			ld de, ntc_buf + 1
			ld bc, 2047
			ldir
			ld hl, lst_h
			ld de, LST_FIRST
			ld bc, lst_n
			call lst_rd4
			ld hl, 0
			ld (lst_cpg), hl
lst_rs_lp:
			ld hl, (lst_n)
			ld a, h
			or l
			jp z, lst_rs_cat
			ld de, (lst_n + 2)
			call lst_rs_sel
			ld e, (hl)				; k = its next
			inc hl
			ld d, (hl)
			inc hl
			ld (lst_k), de
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (lst_k + 2), de
			ld hl, (lst_n)			; A = its key byte
			ld de, (lst_ko)
			add hl, de
			ld a, (lst_byte)
			or a
			ld a, (hl)
			jr z, lst_rs_idx
			inc hl
			ld a, (hl)
			xor #80
lst_rs_idx:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			ld de, LST_TAILS
			add hl, de				; HL = its bucket's tail
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld a, d
			or e
			jr z, lst_rs_empty
			inc hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			dec hl
			dec hl
			dec hl
			push hl
			ex de, hl				; the tail's next = the node
			ld d, b
			ld e, c
			call lst_rs_sel
			ld de, (lst_n)
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld de, (lst_n + 2)
			ld (hl), e
			inc hl
			ld (hl), d
			pop hl
			jr lst_rs_tail
lst_rs_empty:
			dec hl					; an empty bucket: its head = the node
			push hl
			ld de, -1024
			add hl, de
			ld de, (lst_n)
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld de, (lst_n + 2)
			ld (hl), e
			inc hl
			ld (hl), d
			pop hl
lst_rs_tail:
			ld de, (lst_n)			; its tail = the node
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld de, (lst_n + 2)
			ld (hl), e
			inc hl
			ld (hl), d
			ld hl, (lst_k)			; on to the next
			ld (lst_n), hl
			ld hl, (lst_k + 2)
			ld (lst_n + 2), hl
			jp lst_rs_lp
lst_rs_cat:
			ld hl, lst_s1			; the buckets in order: s1 = first, s2 = the last tail
			call lst_zero
			ld hl, lst_s2
			call lst_zero
			ld hl, LST_HEADS
			ld (lst_bp), hl
lst_rs_clp:
			ld hl, (lst_bp)
			call lst_null
			jr z, lst_rs_cnx
			ld hl, lst_s2
			call lst_null
			jr nz, lst_rs_clink
			ld hl, (lst_bp)
			ld de, lst_s1
			call lst_cp4
			jr lst_rs_ct
lst_rs_clink:
			ld hl, lst_s2
			ld de, LST_NEXT
			ld bc, (lst_bp)
			call lst_wr4
lst_rs_ct:
			ld hl, (lst_bp)
			ld de, 1024
			add hl, de
			ld de, lst_s2
			call lst_cp4
lst_rs_cnx:
			ld hl, (lst_bp)
			ld de, 4
			add hl, de
			ld (lst_bp), hl
			ld de, LST_HEADS + 1024
			or a
			sbc hl, de
			jr nz, lst_rs_clp
			ld hl, lst_s2			; the last tail's next = 0
			call lst_null
			jr z, lst_rs_cend
			ld hl, lst_k
			call lst_zero
			ld hl, lst_s2
			ld de, LST_NEXT
			ld bc, lst_k
			call lst_wr4
lst_rs_cend:
			ld hl, lst_h
			ld de, LST_FIRST
			ld bc, lst_s1
			jp lst_wr4

; ============================================================
; ntc_lib_nxt.asm - ZX Spectrum Next platform banking
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ------------------------------------------------------------
; The Next versions of the three banking primitives the CPC-modelled
; Memory manager (ntc_mem, in ntc_lib_cpc.asm) switches platform on:
;   nxt_mem_probe   - the RAM probe (mem_probe's ELSE branch)
;   nxt_mem_jbc     - 64K bank -> its first 16K Next bank (mem_jbc's zxn branch)
;   nxt_mem_se_out  - a RAM setting into the #4000 window (mem_se_out's zxn branch)
; Linked as a dependency of ntc_mem; the whole section is IFDEF NTC_ZXN, so on a
; CPC build it contributes nothing. NextReg is driven through ports #243B / #253B
; (no Z80N opcodes). A 64K "bank" = 4 x 16K Next banks; a 16K bank = two 8K MMU
; pages (slots 2, 3 = NextReg #52, #53) in the #4000-#7FFF window.
;
; The RAM setting (BC) on the Next is shaped as the CPC's gate-array one, so that
; everything built on the CPC's setting arithmetic (a 64K bank's "C2" setting =
; its page 0's and #F8 or 2; its page n in the window = and #F8 or 4 + n) works
; unchanged: B = ZXN_SETB (1 - never 0: 0 in B means "main RAM, no switch" to the
; code that tests it; never #7F: #7FC0 is main RAM's own), C = the 64K bank's
; ordinal (0, 1, 2 ... from ZXN_FIRSTBANK, 4 x 16K each) * 8 + 4 + its 16K page
; (0-3) - or + 2 for the whole bank. nxt_mem_bank decodes it to the 16K Next bank.
; ============================================================

;## ntc_nxt_bank ntc_mem @far
	IFDEF NTC_ZXN
; nxt_mem_probe - the 16K banks from ZXN_FIRSTBANK (2: page n is the Next's bank n, 20261116-6) up:
; which are there. Map each into the
; window, mark it, re-read; the contiguous run that still holds its marker is
; usable. Sets mem_banks (64K banks = usable 16K banks / 4). Called from mem_probe;
; leaves interrupts off (the boot re-enables, as the CPC path does).
; 20261111: the byte each marker goes over is kept (zxn_pr_sv) and put back afterwards,
; highest bank first - the banks hold things: Option Page ... Loaded pages (their code
; starts at #4000), a game's data put in banks by its own build, and on a 1MB Next the
; banks past 47 are aliases of real ones, so a marker there landed on a real bank's
; first byte (the program's own: RANAMAGE's main thread lost a word at #4000). Highest
; first, so an alias's real bank is put back last, with its own byte.
nxt_mem_probe:
			di
			ld c, ZXN_FIRSTBANK
			ld hl, zxn_pr_sv
zxn_pr_w:
			call zxn_pr_own			; (the program's own banks: there, and never marked - the
			jr z, zxn_pr_w2			; program's code is in them, this routine's included)
			call zxn_pr_map			; 16K bank C into #4000-#7FFF
			ld a, (MEM_WIN)
			ld (hl), a				; the byte there, kept
			ld a, c
			ld (MEM_WIN), a			; marker = the bank number
zxn_pr_w2:
			inc hl
			inc c
			ld a, c
			cp ZXN_FIRSTBANK + ZXN_MAXBANK
			jr nz, zxn_pr_w
			ld b, 0					; usable 16K banks
			ld c, ZXN_FIRSTBANK
zxn_pr_r:
			call zxn_pr_own
			jr z, zxn_pr_r2
			call zxn_pr_map
			ld a, (MEM_WIN)
			cp c					; still its own marker (real, not absent / aliased)?
			jr nz, zxn_pr_done
zxn_pr_r2:
			inc b
			inc c
			ld a, c
			cp ZXN_FIRSTBANK + ZXN_MAXBANK
			jr nz, zxn_pr_r
zxn_pr_done:
			push bc					; B = usable banks
			ld c, ZXN_FIRSTBANK + ZXN_MAXBANK - 1
			ld hl, zxn_pr_sv + ZXN_MAXBANK - 1
zxn_pr_rs:
			call zxn_pr_own
			jr z, zxn_pr_rs2
			call zxn_pr_map			; every bank's byte back, highest first
			ld a, (hl)
			ld (MEM_WIN), a
zxn_pr_rs2:
			dec hl
			ld a, c
			cp ZXN_FIRSTBANK
			jr z, zxn_pr_rsd
			dec c
			jr zxn_pr_rs
zxn_pr_rsd:
			pop bc
			ld c, 1					; the program's own window bank back
			call zxn_pr_map
			ld a, b
			ld (zxn_usable), a		; pages 2 .. usable + 1 are there
			add a, 3				; 64K banks = usable 16K banks / 4, rounded up: the pages of the last
			srl a					; one that are not there are marked taken (mem_tb_zx)
			srl a
			ld (mem_banks), a
			or a
			jr z, zxn_pr_nf
			ld hl, mem_found		; the banks found, 0, 1, 2 ... (contiguous on the Next)
			ld b, a
			ld e, 0
zxn_pr_fl:
			ld (hl), e
			inc hl
			inc e
			djnz zxn_pr_fl
zxn_pr_nf:
			ret
zxn_pr_sv:	ds ZXN_MAXBANK			; the probe's kept bytes (one a bank)
zxn_usable:	db 0					; the 16K banks found from ZXN_FIRSTBANK up
; zxn_pr_own - C = a 16K bank: Z when it is one of the program's own (0, 1, 2: #0000-#BFFF; 5:
; #C000-#FFFF). Keeps BC, DE, HL
zxn_pr_own:
			ld a, c
			cp 5
			ret z
			cp 3
			jr nc, zxn_pr_no		; 0, 1, 2: its own
			xor a
			ret
zxn_pr_no:
			or 1					; NZ
			ret
; zxn_pr_map - C = a 16K bank into #4000-#7FFF (MMU slots 2, 3 = NextReg #52, #53). Keeps C.
zxn_pr_map:
			push bc
			ld a, c
			add a, a				; first 8K page = bank * 2
			ld d, a
			ld bc, #243B
			ld a, #52
			out (c), a
			inc b
			out (c), d
			dec b
			ld a, #53
			out (c), a
			inc b
			inc d
			out (c), d
			pop bc
			ret

ZXN_SETB	equ 1					; B of a Next RAM setting (see the top)

; nxt_mem_jbc - E = a 64K bank (0-63) -> BC = its page 0's RAM setting (B = ZXN_SETB,
; C = E * 8 + 4: the four 16K parts step C, as the CPC's #C4, #C5, #C6, #C7 do). Called
; from mem_jbc (jp, so its ret returns to mem_jbc's caller). Keeps DE, HL.
nxt_mem_jbc:
			ld a, e
			add a, a
			add a, a
			add a, a				; E * 8
			add a, 4				; + 4: its page 0
			ld c, a
			ld b, ZXN_SETB
			ret

; nxt_mem_bank - BC = a RAM setting -> A = its 16K Next bank: B = #7F (main RAM's own,
; #7FC0) = bank 1 (the program's own window); else C = ordinal * 8 + 4 + page
; -> ZXN_FIRSTBANK + ordinal * 4 + page (the whole bank's "2" and the pages 0-3
; (#C0-#C3 on the CPC: main RAM's blocks) all give its page 0). Keeps BC, DE, HL.
nxt_mem_bank:
			ld a, b
			cp #7F
			jr nz, nxt_mb_pg
			ld a, 1
			ret
nxt_mb_pg:
			ld a, c
			and 7
			sub 4
			jr nc, nxt_mb_ok
			xor a					; 0-3: page 0
nxt_mb_ok:
			push de
			ld e, a
			ld a, c
			and #F8
			srl a					; ordinal * 4
			add a, e
			add a, ZXN_FIRSTBANK
			pop de
			ret

; nxt_win - BC = a RAM setting -> its 16K Next bank into the window #4000-#7FFF (MMU
; slots 2, 3): what out (c), c does with a setting on the CPC - for a program's own asm
; (CyborgOS's hypervisor) that switches the window itself, outside the Memory class
; (ntc_rampt is not touched, as the CPC's out doesn't). Keeps every register, as the out
; does (AF too). ntc_zxsel is kept for the interrupt handler's re-select. On the real
; stack only (call: never from the thread)
nxt_win:
			push af
			push bc
			push de
			call nxt_mem_bank		; A = the 16K Next bank
			add a, a				; its first 8K page
			ld d, a
			ld bc, #243B
			ld a, #52
			ld (ntc_zxsel), a
			out (c), a
			inc b
			out (c), d				; MMU slot 2 = the page
			dec b
			ld a, #53
			ld (ntc_zxsel), a
			out (c), a
			inc b
			inc d
			out (c), d				; MMU slot 3 = page + 1
			pop de
			pop bc
			pop af
			ret

; nxt_mem_se_out - BC = the RAM setting (B = ZXN_SETB, C = the bank's ordinal * 8 + 4 +
; page: nxt_mem_bank): the Next 16K bank into the window (slots 2, 3). B = #7F (page 1 /
; plain RAM) = the program's own window bank 1. Reached by jp from mem_se_out; exits
; through mem_se_end. Called on the real stack (mem_sel pushed there).
; ntc_zxsel is kept so an interrupt handler can re-assert the window.
nxt_mem_se_out:
			ld (ntc_rampt), bc
			call nxt_mem_bank			; A = the 16K Next bank (B = #7F: main RAM's own, bank 1)
			add a, a					; first 8K page = Next 16K bank * 2
			ld d, a
			ld bc, #243B
			ld a, #52
			ld (ntc_zxsel), a
			out (c), a
			inc b
			out (c), d
			dec b
			ld a, #53
			ld (ntc_zxsel), a
			out (c), a
			inc b
			inc d
			out (c), d
			jp mem_se_end
	ENDIF

; ============================================================
; ntc_lib_msx.asm - MSX-DOS 2 / Nextor platform banking (msxdos)
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ------------------------------------------------------------
; The MSX versions of the banking primitives the CPC-modelled Memory
; manager (ntc_mem, in ntc_lib_cpc.asm) switches platform on, as the
; Next's are in ntc_lib_nxt.asm:
;   msx_mem_probe   - the mapper's segments (mem_probe's MSX branch)
;   msx_mem_jbc     - 64K bank -> its page 0's RAM setting (mem_jbc's)
;   msx_mem_se_out  - a RAM setting into the window #4000-#7FFF (mem_se_out's)
;   msx_win         - the same for a program's own asm (CyborgOS), as out (c), c
;   msx_mem_bank    - a RAM setting -> its segment
; The whole section is IFDEF NTC_MSXDOS: nothing on any other platform.
;
; The mapper's 16K segments come from MSX-DOS 2's mapper support (EXTBIO
; #FFCA, D = 4, E = 2: the jump table): ALL_SEG takes every free user segment
; of the primary mapper at the probe (MSX-DOS 2 frees them when the program
; ends), 4 a 64K "bank" in the order given (a bank's 4 needn't be next to each
; other: its segments are looked up, msx_segs). The window is page 1, changed
; with PUT_P1 so that MSX-DOS 2 knows what is in it (a BDOS call reading into
; the window reads into that segment). Main RAM's own page 1 (the setting
; #7FC0) is the segment the program started with (GET_P1).
;
; The RAM setting (BC) is shaped as the CPC's gate-array one, as on the Next,
; so that the CPC's setting arithmetic (a bank's "C2" setting = its page 0's
; and #F8 or 2; its page n in the window = and #F8 or 4 + n) works unchanged:
; B = MSX_SETB (1 - never 0, never #7F), C = the bank's ordinal * 8 + 4 + its
; page (0-3), or + 2 for the whole bank.
; ============================================================

;## ntc_msx_bank ntc_mem @far
	IFDEF NTC_MSXDOS
MSX_SETB	equ 1					; B of an MSX RAM setting (see the top)
MSX_ALL		equ 0					; the jump table: ALL_SEG
MSX_FRE		equ 3					; FRE_SEG
MSX_PUT1	equ 30					; PUT_P1
MSX_GET0	equ 27					; GET_P0 (then GET_P1 30 + 3 ...: every 6)
	IF MEM_BANKS > 31
MSX_MAXSEG	equ 31 * 4				; segments taken at most: 31 banks (a setting's C = ordinal * 8 + ...: 0-31)
	ELSE
MSX_MAXSEG	equ MEM_BANKS * 4
	ENDIF

msx_mtab:		dw 0					; MSX-DOS 2's mapper support jump table (0: none)
msx_tpa:		db 0, 0, 0, 0			; the program's own segments, pages 0-3 (GET_Pn)
msx_nseg:		db 0					; segments in msx_segs
msx_segs:		ds MEM_BANKS * 4 + 4	; the segments, 4 a bank

; msx_mc - call the mapper support routine at offset E (A, B its arguments), on
; the real stack. Keeps DE; the routine's A, B, flags back
msx_mc:
			push de
			ld hl, (msx_mtab)
			ld d, 0
			add hl, de
			pop de
			jp (hl)

; msx_mem_probe - the mapper support's table (no MSX-DOS 2 / Nextor: none, no
; pages), the program's own segments, then every free user segment of the
; primary mapper, 4 a bank (up to MEM_BANKS); a part bank's are given back.
; Sets mem_banks and mem_found. Called from mem_probe on the real stack
msx_mem_probe:
			ld a, (#FB20)			; HOKVLD: bit 0 = EXTBIO is there
			and 1
			ret z
			xor a
			ld de, #0402			; mapper support: the jump table
			call #FFCA				; EXTBIO: HL = the table, A = segments (0: no mapper support)
			di
			or a
			ret z
			ld a, h
			or l
			ret z
			ld (msx_mtab), hl
			ld e, MSX_GET0			; GET_P0 .. GET_P3: the program's own
			ld hl, msx_tpa
			ld b, 4
msx_pr_own:
			push bc
			push de
			push hl
			call msx_mc
			di
			pop hl
			pop de
			pop bc
			ld (hl), a
			inc hl
			ld a, e
			add a, 6
			ld e, a
			djnz msx_pr_own
			ld hl, msx_segs
msx_pr_all:
			ld a, (msx_nseg)
			cp MSX_MAXSEG
			jr nc, msx_pr_done
			push hl
			xor a					; a user segment
			ld b, a					; of the primary mapper
			ld e, MSX_ALL
			call msx_mc
			di
			pop hl
			jr c, msx_pr_done		; (none left)
			ld (hl), a
			inc hl
			ld a, (msx_nseg)
			inc a
			ld (msx_nseg), a
			jr msx_pr_all
msx_pr_done:
			ld a, (msx_nseg)		; a part bank's segments back
			and 3
			jr z, msx_pr_banks
			ld b, a
msx_pr_fre:
			dec hl
			push bc
			push hl
			ld a, (hl)
			ld b, 0
			ld e, MSX_FRE
			call msx_mc
			di
			pop hl
			pop bc
			ld a, (msx_nseg)
			dec a
			ld (msx_nseg), a
			djnz msx_pr_fre
msx_pr_banks:
			ld a, (msx_nseg)
			srl a
			srl a					; 64K banks
			ld (mem_banks), a
			or a
			ret z
			ld hl, mem_found		; the banks found: 0, 1, 2 ...
			ld b, a
			ld e, 0
msx_pr_fl:
			ld (hl), e
			inc hl
			inc e
			djnz msx_pr_fl
			ret

; msx_mem_jbc - E = a 64K bank (0-63) -> BC = its page 0's RAM setting (B = MSX_SETB,
; C = E * 8 + 4: the four 16K parts step C, as the CPC's #C4 - #C7 do). Keeps DE, HL.
msx_mem_jbc:
			ld a, e
			add a, a
			add a, a
			add a, a
			add a, 4
			ld c, a
			ld b, MSX_SETB
			ret

; msx_mem_bank - BC = a RAM setting -> A = its segment: B = #7F (main RAM's own,
; #7FC0) = the program's own page 1; else C = ordinal * 8 + 4 + page ->
; msx_segs(ordinal * 4 + page) (the whole bank's "2" and 0-3: its page 0).
; Keeps BC, DE, HL.
msx_mem_bank:
			ld a, b
			cp #7F
			jr nz, msx_mb_pg
			ld a, (msx_tpa + 1)
			ret
msx_mb_pg:
			push hl
			push de
			ld a, c
			and 7
			sub 4
			jr nc, msx_mb_ok
			xor a					; 0-3: page 0
msx_mb_ok:
			ld e, a
			ld a, c
			and #F8
			srl a					; ordinal * 4
			add a, e
			ld e, a
			ld d, 0
			ld hl, msx_segs
			add hl, de
			ld a, (hl)
			pop de
			pop hl
			ret

; msx_win - BC = a RAM setting -> its segment into the window #4000-#7FFF (PUT_P1):
; what out (c), c does with a setting on the CPC - for a program's own asm (CyborgOS)
; that switches the window itself, outside the Memory class (ntc_rampt is not
; touched, as the CPC's out doesn't). Keeps every register, as the out does (AF too;
; interrupts as they were). On the real stack only (call: never from the thread)
msx_win:
			push af
			push bc
			push de
			push hl
			call msx_mem_bank
			ld e, MSX_PUT1
			call msx_mc
			pop hl
			pop de
			pop bc
			pop af
			ret

; msx_mem_se_out - BC = the RAM setting: its segment into the window (PUT_P1). Reached
; by jp from mem_se_out; exits through mem_se_end. On the real stack (mem_sel pushed there)
msx_mem_se_out:
			ld (ntc_rampt), bc
			call msx_mem_bank
			ld e, MSX_PUT1
			call msx_mc
			jp mem_se_end
	ENDIF

; ============================================================
; ntc_lib_dot.asm - ZX Spectrum Next dot command (zxndotl) banking
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ------------------------------------------------------------
; The Large Model dot command's versions of the banking primitives the
; CPC-modelled Memory manager (ntc_mem, in ntc_lib_cpc.asm) switches
; platform on, as the Next's NEX ones are in ntc_lib_nxt.asm and the MSX's
; in ntc_lib_msx.asm:
;   dot_mem_probe   - 8K pages from NextZXOS's allocator, 8 a 64K bank
;   dot_mem_jbc     - 64K bank -> its page 0's RAM setting
;   dot_mem_se_out  - a RAM setting into the window #4000-#7FFF (slots 2, 3)
;   dot_mem_bank    - a RAM setting -> its first 8K page's index in dotl_pages
;   dot_win         - the window switch for a program's own asm, as out (c), c
; The whole section is IFDEF NTC_ZXNDOTL: nothing on any other platform.
;
; The pages come from IDE_BANK (through M_P3DOS, on BASIC's side: dotl_page in
; the platform's entry code, which keeps them in dotl_pages and gives every one
; back at the end). The first 6 are the platform's (the window's two, the
; program's four); the Memory class's follow, 8 a 64K bank (4 x 16K, a 16K bank
; = two 8K pages, one after the other in dotl_pages - any page numbers, the
; allocator's choice). The window is slots 2 and 3 (NextRegs #52, #53). Main
; RAM's own page 1 (the setting #7FC0) is the window's own two pages.
;
; The RAM setting (BC) is shaped as the CPC's gate-array one, so that the CPC's
; setting arithmetic (a bank's "C2" setting = its page 0's and #F8 or 2; its
; page n in the window = and #F8 or 4 + n) works unchanged: B = DOT_SETB (1 -
; never 0, never #7F), C = the bank's ordinal * 8 + 4 + its page (0-3), or + 2
; for the whole bank.
; ============================================================

;## ntc_dot_bank ntc_mem @far
	IFDEF NTC_ZXNDOTL
DOT_SETB	equ 1					; B of a dot command's RAM setting (see the top)
	IF MEM_BANKS > 16
DOT_MAXBK	equ 16					; banks at most: dotl_pages holds 16 (1MB)
	ELSE
DOT_MAXBK	equ MEM_BANKS
	ENDIF
; dot_mem_probe - up to DOT_MAXBK banks of 8 pages from the allocator; a part bank's
; pages stay allocated (given back at the end with the rest: the allocator has no
; order to free them in). Sets mem_banks and mem_found. Called from mem_probe on the
; real stack
dot_mem_probe:
			xor a
			ld (dot_nbk), a
dot_pr_bank:
			ld a, (dot_nbk)
			cp DOT_MAXBK
			jr nc, dot_pr_done
			ld b, 8
dot_pr_pg:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dot_pr_done		; none left: this bank is not whole
			djnz dot_pr_pg
			ld a, (dot_nbk)
			inc a
			ld (dot_nbk), a
			jr dot_pr_bank
dot_pr_done:
			ld a, (dot_nbk)
			ld (mem_banks), a
			or a
			ret z
			ld hl, mem_found		; the banks found: 0, 1, 2 ...
			ld b, a
			ld e, 0
dot_pr_fl:
			ld (hl), e
			inc hl
			inc e
			djnz dot_pr_fl
			ret
dot_nbk:		db 0					; banks got

; dot_mem_jbc - E = a 64K bank (0-63) -> BC = its page 0's RAM setting (B = DOT_SETB,
; C = E * 8 + 4: the four 16K parts step C, as the CPC's #C4 - #C7 do). Keeps DE, HL.
dot_mem_jbc:
			ld a, e
			add a, a
			add a, a
			add a, a
			add a, 4
			ld c, a
			ld b, DOT_SETB
			ret

; dot_mem_bank - BC = a RAM setting -> HL = its two pages' place in dotl_pages: B = #7F
; (main RAM's own, #7FC0) = the window's own (dotl_pages + 0); else C = ordinal * 8 +
; 4 + page -> dotl_pages + 6 + (ordinal * 4 + page) * 2 (the whole bank's "2" and 0-3:
; its page 0). Keeps BC, DE.
dot_mem_bank:
			ld hl, dotl_pages
			ld a, b
			cp #7F
			ret z
			push de
			ld a, c
			and 7
			sub 4
			jr nc, dot_mb_ok
			xor a					; 0-3: page 0
dot_mb_ok:
			ld e, a
			ld a, c
			and #F8
			srl a					; ordinal * 4
			add a, e
			add a, a				; two pages a 16K bank
			add a, 6				; after the platform's 6
			ld e, a
			ld d, 0
			add hl, de
			pop de
			ret

; dot_mem_se_out - (mem_se_out's branch) BC = a RAM setting: its two pages into slots
; 2, 3 -> mem_se_end (which pops BC, DE, HL)
dot_mem_se_out:
			call dot_win
			jp mem_se_end

; dot_win - BC = a RAM setting -> its two pages into the window #4000-#7FFF (NextRegs
; #52, #53): what out (c), c does with a setting on the CPC - for a program's own asm
; that switches the window itself, outside the Memory class. Keeps every register, as
; the out does (AF too). On the real stack only (call: never from the thread)
dot_win:
			push af
			push bc
			push de
			push hl
			call dot_mem_bank		; HL -> the two pages
			ld d, (hl)
			inc hl
			ld e, (hl)
			ld bc, #243B
			ld a, #52
			out (c), a
			inc b
			out (c), d				; slot 2
			dec b
			ld a, #53
			out (c), a
			inc b
			out (c), e				; slot 3
			pop hl
			pop de
			pop bc
			pop af
			ret
	ENDIF

;## ntc_ep_bank ntc_mem @far
	IFDEF NTC_EP128
EPB_SEG1	equ #BCFE				; the platform's start code leaves these for this section, at fixed places (the
EPB_NSEG	equ #BCFF				; library names no platform label): the program's page 1 segment, the number of
EPB_SEGS	equ #BD00				; free segments, and their list
ep_usable:		db 0					; the pages there are after page 1 (segments in the list, Option Memory's limit kept)

; ep_mem_probe - the segments the start code listed, 4 a bank (up to MEM_BANKS;
; a last bank of fewer than 4 counts). Sets mem_banks, mem_found and ep_usable.
; Called from mem_probe on the real stack
ep_mem_probe:
			ld a, (EPB_NSEG)
	IF MEM_BANKS < 63				; (Option Memory Heap Pages n: no more than its pages)
			cp MEM_BANKS * 4 + 1
			jr c, ep_pr_n
			ld a, MEM_BANKS * 4
ep_pr_n:
	ENDIF
			ld (ep_usable), a
			add a, 3				; banks = (segments + 3) / 4 (252 segments at most: no carry)
			srl a
			srl a
			ld (mem_banks), a
			or a
			ret z
			ld hl, mem_found		; the banks found: 0, 1, 2 ...
			ld b, a
			ld e, 0
ep_pr_fl:
			ld (hl), e
			inc hl
			inc e
			djnz ep_pr_fl
			ret

; ep_mem_jbc - E = a 64K bank (0-63) -> BC = its page 0's RAM setting (B = 1 + E / 32,
; C = (E and 31) * 8 + 4: the four 16K parts step C, as the CPC's #C4 - #C7 do).
; Keeps DE, HL.
ep_mem_jbc:
			ld a, e
			add a, a
			add a, a
			add a, a
			add a, 4
			ld c, a
			ld a, e
			rlca
			rlca
			rlca
			and 1
			inc a
			ld b, a
			ret

; ep_mem_seg - BC = a RAM setting -> A = its segment: B = #7F (main RAM's own,
; #7FC0) = the program's own page 1; else EPB_SEGS((B - 1) * 128 + (C and #F8) / 2 +
; page), the page C's low 3 bits less 4 (the whole bank's "2" and 0-3: its page 0).
; Keeps BC, DE, HL.
ep_mem_seg:
			ld a, b
			cp #7F
			jr nz, ep_ms_pg
			ld a, (EPB_SEG1)
			ret
ep_ms_pg:
			push hl
			ld a, c
			and 7
			sub 4
			jr nc, ep_ms_ok
			xor a					; 0-3: page 0
ep_ms_ok:
			ld l, a
			ld a, c
			and #F8
			srl a					; (bank and 31) * 4
			add a, l
			ld l, a
			ld a, b
			dec a
			rrca					; bank / 32: bit 7
			and #80
			or l
			ld l, a
			ld h, high EPB_SEGS
			ld a, (hl)
			pop hl
			ret

; ep_mem_se_out - BC = the RAM setting: its segment into the window (page 1, port #B1).
; Reached by jp from mem_se_out; exits through mem_se_end. ntc_rampt first, then the port
ep_mem_se_out:
			ld (ntc_rampt), bc
			call ep_mem_seg
			out (#B1), a
			jp mem_se_end
	ENDIF

;## ntc_plat_exit
; ntc_plat_exit - back to BASIC: the pages given back, its memory in slots 2-7, its
; stack, carry clear (0 OK), interrupts on - dotl_exit, in the entry's 8K
ntc_plat_exit:
			jp dotl_exit			; (in the entry's 8K: the program's own pages are unmapped on the way)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not use:
; #FF80, under the real stack (128 bytes from #FFFF down). Called on the real stack
; (call / ret), only by the Memory class
ntc_plat_memtop:
			ld hl, #FF80
			ret

; ============================================================
; NTC Platform - ZX Spectrum Next, a dot command: the Small Model
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ============================================================
; No call, no push: SP stays in the thread. Every routine is
; entered with jp, return address in IX, and ends with jp (ix).
;
; A NextZXOS / esxDOS dot command: NAME.DOT in C:/DOT, typed as .name args
; at the BASIC prompt. NextZXOS loads the file at #2000 into DivMMC's 8K
; page and calls it with HL = the arguments (0: none), BC = the whole line,
; SP = BASIC's stack; it returns with ret, carry clear (0 OK), or carry set
; and A = an esxDOS error, or A = 0 and HL = its own message (bit 7 on the
; last character). The BASIC program, its variables and its screen are kept
; as found: this is a utility that runs and comes back, not a program that
; owns the machine (that is the zxn platform: a NEX file).
;
; Memory  the 8K at #2000-#3FFF, and nothing else: the code, its data, the
;         arrays (ntc_free must end by #4000: the assembly says so when not),
;         the real stack (dot_stack, 128 bytes in the data). Option Memory
;         Small: the heap is what is left up to #4000 (ntc_plat_memtop). The
;         Large Model (zxndotl, built on this one) has 32K and banks.
;           #0000-#1FFF  DivMMC's ROM (esxDOS: rst 8 the file calls, rst #10 /
;                        rst #18 the 48K ROM's print and routines)
;           #2000-#3FFF  this dot command
;           #4000-#FFFF  BASIC's: the screen, the system variables, its
;                        program and stack - not touched
; Console text goes to BASIC's screen through the 48K ROM's rst #10 (the
;         current channel: the upper screen, opened at the start), so it
;         prints as every dot command does - in the mode BASIC is in, scrolling,
;         "scroll?" and all. Cls is the ROM's CLS, Locate the AT control code
;         (22, row, column), Mode does nothing. 32 columns, 24 rows are
;         counted (the ROM wraps and scrolls itself). Keys come from the ROM's
;         keyboard scan (LAST_K, set by its interrupt): Enter 13, Delete 127,
;         the cursor keys the CPC firmware's codes (up 240, down 241, left 242,
;         right 243), as the zxn platform gives them.
; The ROM  (the sections that switch to the real stack for dot_os are @shared: one
;         copy, no normal mode rewrite of their SP loads - as cpm's ntc_bdos)
;         a ROM routine (rst #10, rst #18, M_P3DOS) pages DivMMC out while
;         it runs, so this 8K is not there then: such a call runs on BASIC's
;         stack (SP as the command was entered) through dot_os, with IY the
;         ROM's (ERR_NR, #5C3A), IM 1 and interrupts on for the ROM's keyboard
;         and "scroll?".
; Interrupts  while the program runs the Z80 is in IM 2 with a vector and a
;         handler of its own in this 8K (dot_irq: it counts dot_frames), so the
;         ROM's handler at #0038 - which would page DivMMC out under a stack in
;         this 8K, or run over nothing of BASIC's with the Large Model's pages in
;         the slots - never runs then. Normal mode's safe points let interrupts in
;         as on every platform (the handler only touches this 8K). The vector
;         table is 257 bytes of which only the last two are read (the data bus
;         gives #FF): the rest holds the entry's two small stacks.
; Frame   waits for the next interrupt (dot_frames moving on); Ticks is
;         dot_frames: the frames counted here, plus FRAMES' advance during the
;         ROM calls (dot_os adds it), 50 a second.
; Command line  System.CommandLine: the arguments, copied at entry into
;         ntc_cmdbuf (up to 127 characters), ended at #0D, ':' (outside
;         quotes) or 0 - before anything can move BASIC's line.
; End     ntc_plat_exit: SP back, carry clear, ei, ret - the BASIC prompt
;         prints 0 OK and the program is as it was.
; Files   none yet (the FileSystem class is not on this platform; esxDOS's
;         F_OPEN / F_READ ... through rst 8 are the way, later).
; ============================================================
;@text     byte
;@scrinit  0
;@irq      0
;@cols     32
;@rows     24
;@dotfile  1
; ============================================================

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 32			; columns
ntc_smode:		db 1			; screen mode (nothing here: 32 columns)
			ds 128
dot_stack:						; the program's real stack (;@stack): 128 bytes, in the 8K

;## ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_putc - A = character: rst #10 on BASIC's side, the column counted (the
; ROM wraps at the edge: so does the count)
ntc_plat_putc:
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; wrapped: the ROM moved to the next row
			ld hl, ntc_cury
			inc (hl)
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - 13 (the ROM's new line)
ntc_plat_newline:
			ld a, 13
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 24
			jr c, ntc_nl_row
			ld a, 23				; (the ROM scrolls)
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key ntc_data @shared
; ntc_plat_scankey - A = key or 0: the ROM's LAST_K after a frame (its interrupt
; scans the keyboard), the ROM's codes made the platform's: Enter 13, Delete (12)
; 127, the cursor keys (8-11) 242, 243, 241, 240; other control codes 0
ntc_plat_scankey:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_kread
			call dot_os
			ld sp, (ntc_ip)
			cp 32
			jr nc, ntc_sk_done		; a character
			cp 13
			jr z, ntc_sk_done
			cp 12
			jr nz, ntc_sk_cur
			ld a, 127				; Delete
			jr ntc_sk_done
ntc_sk_cur:
			cp 8
			jr c, ntc_sk_none
			cp 12
			jr nc, ntc_sk_none
			ld hl, ntc_sk_tab - 8
			add a, l
			ld l, a
			jr nc, ntc_sk_rd
			inc h
ntc_sk_rd:
			ld a, (hl)
			jr ntc_sk_done
ntc_sk_none:
			xor a
ntc_sk_done:
			jp (ix)
ntc_sk_tab:		db 242, 243, 241, 240	; left, right, down, up

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_rmr ntc_plat_data
; ntc_plat_rmr - no CPC gate-array ROM/mode byte here: the screen mode byte, BC, DE,
; HL kept (the Memory class's CallBank)
ntc_plat_rmr:
			ld a, (ntc_smode)
			ret


ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack 0 down (the platform's)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #FF80, "zxndotl: the program and its arrays must end by #FF80 (the 32K at #8000, less the stack)"
